- [개인정보 처리방침 검토](docs/privacy.md) · 화면: `/privacy`, 이용약관 `/terms`
- [QA 기록](docs/qa.md)
// 로컬(테스트) D1 을 비우고 마이그레이션을 적용한 뒤 개발업체 하나(소유자 owner@studio.test)를 만든다.
//
//   node scripts/db-local.mjs [--persist-to .wrangler/test-state]
import { spawnSync } from 'node:child_process';
import { rmSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('..', import.meta.url));
const i = process.argv.indexOf('--persist-to');
const persist = i > 0 ? process.argv[i + 1] : '.wrangler/test-state';
rmSync(join(root, persist), { recursive: true, force: true });
const run = (args) => {
  const r = spawnSync('npx', args, { cwd: root, stdio: 'inherit' });
  if (r.status !== 0) process.exit(r.status ?? 1);
};
run(['wrangler', 'd1', 'migrations', 'apply', 'DB', '--local', '--persist-to', persist]);
run(['node', 'scripts/admin.mjs', 'add-workspace', '--name', '테스트개발사', '--email', 'owner@studio.test', '--owner', '김대표', '--persist-to', persist]);
run(['node', 'scripts/admin.mjs', 'add-user', '--email', 'ops@irumx.test', '--name', '운영자', '--persist-to', persist]);
// 운영 배포: 빌드(점검 포함) → D1 마이그레이션 → wrangler deploy → 운영 주소에서 결과 확인.
//
//   set -a; . ~/.config/yeopjari/cloud.env; set +a
//   CLOUDFLARE_API_TOKEN=$CF_API_TOKEN CLOUDFLARE_ACCOUNT_ID=$CF_ACCOUNT_ID npm run deploy
//   node scripts/deploy.mjs --verify-only     (배포 없이 운영 확인만)
//
// 'Deployment complete' 를 믿지 않고, 운영 주소가 방금 만든 파일을 바이트 단위로 돌려주는지와 보안 동작을 확인한다.
import { spawnSync } from 'node:child_process';
import { readdirSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { join } from 'node:path';

const root = fileURLToPath(new URL('..', import.meta.url));
const LIVE = 'https://client.irumx.app';
// 약관 버전은 화면 코드와 같은 값을 읽는다(terms.html 의 ‘버전 …’과 맞는지 운영에서 확인)
const TERMS_VERSION = readFileSync(join(root, 'src/shared/domain.ts'), 'utf8').match(/TERMS_VERSION = '([^']+)'/)[1];
const verifyOnly = process.argv.includes('--verify-only');

function run(cmd, args) {
  console.log(`\n$ ${cmd} ${args.join(' ')}`);
  const r = spawnSync(cmd, args, { cwd: root, stdio: 'inherit' });
  if (r.status !== 0) {
    console.error(`실패: ${cmd} ${args.join(' ')} (종료 코드 ${r.status})`);
    process.exit(r.status ?? 1);
  }
}

if (!verifyOnly) {
  for (const k of ['CLOUDFLARE_API_TOKEN', 'CLOUDFLARE_ACCOUNT_ID'])
    if (!process.env[k]) {
      console.error(`${k} 가 없다. 배포 셸에서 export 한 뒤 다시 실행한다.`);
      process.exit(1);
    }
  run('npm', ['run', 'build']);
  run('npx', ['wrangler', 'd1', 'migrations', 'apply', 'DB', '--remote']);
  run('npx', ['wrangler', 'deploy']);
}

const get = (path, init) => fetch(LIVE + path, { redirect: 'manual', ...init });
const local = readFileSync(join(root, 'dist/client/index.html'));
let ok = false;
for (let i = 0; i < 60 && !ok; i++) {
  const res = await get(`/?v=${Date.now()}`, { cache: 'no-store' }).catch(() => null);
  ok = !!res && res.status === 200 && Buffer.from(await res.arrayBuffer()).equals(local);
  if (!ok) await new Promise((r) => setTimeout(r, 5000));
}
if (!ok) {
  console.error('운영 index.html 이 로컬 빌드와 다르다(전파 지연이거나 배포 실패).');
  process.exit(1);
}
const checks = [];
const appHtml = readFileSync(join(root, 'dist/client/app.html'), 'utf8');
const appJs = appHtml.match(/\/assets\/[^"]+\.js/)?.[0];
if (appJs) checks.push([`${appJs} 일치`, Buffer.from(await (await get(appJs)).arrayBuffer()).equals(readFileSync(join(root, 'dist/client', appJs)))]);
// 나눠 받는 화면 조각(업체·프로젝트·운영자)도 같은 바이트로, 없는 조각은 앱 셸이 아니라 404 로
for (const f of readdirSync(join(root, 'dist/client/assets')).filter((x) => /^(project|studio|ops|inquiry)-.*\.js$/.test(x))) {
  checks.push([`/assets/${f} 일치`, Buffer.from(await (await get(`/assets/${f}`)).arrayBuffer()).equals(readFileSync(join(root, 'dist/client/assets', f)))]);
}
checks.push(['없는 조각 404(옛 탭은 새로 고침)', (await get('/assets/project-gone0000.js')).status === 404]);
const shell = await get('/p/abcdefghijkmnpqr');
const sh = shell.headers;
const shellBody = await shell.text();
checks.push([`화면 주소 → 앱 셸(${shell.status})`, shell.status === 200 && shellBody.includes('id="root"')]);
checks.push(['앱 셸 CSP·no-store·noindex', (sh.get('content-security-policy') ?? '').includes("script-src 'self'") && (sh.get('cache-control') ?? '').includes('no-store') && (sh.get('x-robots-tag') ?? '').includes('noindex')]);
checks.push(['HSTS', !!sh.get('strict-transport-security')]);
const me = await get('/api/me');
checks.push([`/api/me 비로그인(${me.status})`, me.status === 200 && (await me.text()).includes('"user":null')]);
checks.push([`프로젝트 API 비로그인 401`, (await get('/api/p/abcdefghijkmnpqr')).status === 401]);
checks.push([`파일 비로그인 401`, (await get('/api/files/abcdefghijkmnpqr')).status === 401]);
checks.push(['시험 전용 오류 경로 닫힘(404)', (await get('/api/__test/boom')).status === 404]);
checks.push(['운영자 주소 조회 비로그인 401', (await get('/api/ops/lookup?email=a%40b.c')).status === 401]);
checks.push(['없는 공개 문의 양식 404', (await get('/api/public/forms/abcdefghijkmnpqr')).status === 404]);
checks.push(['공개 문의 화면 → 앱 셸', (await get('/inquiry/abcdefghijkmnpqr')).status === 200]);
checks.push([`파일 목록·알림 설정 비로그인 401`, (await get('/api/p/abcdefghijkmnpqr/files')).status === 401 && (await get('/api/me/notifications')).status === 401]);
const forged = await get('/api/me', { method: 'POST', headers: { Origin: 'https://evil.example', 'Content-Type': 'application/json' }, body: '{}' });
checks.push([`다른 출처 쓰기 403(${forged.status})`, forged.status === 403]);
const otp = await get('/api/auth/email-otp/send-verification-otp', { method: 'POST', headers: { Origin: LIVE, 'Content-Type': 'application/json' }, body: JSON.stringify({ email: 'nobody@example.invalid', type: 'sign-in' }) });
checks.push([`로그인 코드 API(${otp.status}, 초대 안 된 주소는 보내지 않음)`, otp.status === 200]);
checks.push(['개인정보 처리방침 200', (await get('/privacy')).status === 200]);
const terms = await get('/terms');
checks.push([`이용약관 200(${TERMS_VERSION})`, terms.status === 200 && (await terms.text()).includes(`버전 ${TERMS_VERSION}`)]);
const robots = await (await get('/robots.txt')).text();
checks.push(['robots.txt', robots.includes('Allow: /$') && robots.includes('Disallow: /')]);
const font = await get('/fonts/irumx-ui.woff2', { method: 'HEAD' });
checks.push([`글꼴 immutable(${font.status})`, font.status === 200 && (font.headers.get('cache-control') ?? '').includes('immutable')]);
for (const [name, pass] of checks) console.log(`${pass ? '✓' : '✗'} ${name}`);
if (checks.some(([, p]) => !p)) process.exit(1);
