/**
 * API 시험 도우미 — 사람마다 따로 로그인한 요청 컨텍스트.
 * 로그인 코드는 가짜 Resend(:8799)가 받은 메일에서 읽는다. 접속 IP 는 사람마다 다르게(로그인 속도 제한 회피 —
 * 운영에서는 Cloudflare 가 CF-Connecting-IP 를 덮어쓰므로 사용자가 바꿀 수 없다).
 */
import { expect, request, type APIRequestContext, type APIResponse } from '@playwright/test';
import { createHash, randomBytes } from 'node:crypto';
import { existsSync, mkdirSync } from 'node:fs';

export const BASE = 'http://127.0.0.1:8798';
export const MOCK = 'http://127.0.0.1:8799';
export const OWNER = 'owner@studio.test';
export const OPERATOR = 'ops@irumx.test';
export const run = `${Date.now().toString(36)}${randomBytes(2).toString('hex')}`;
export const fakeIp = () => `10.${randomBytes(1)[0]}.${randomBytes(1)[0]}.${(randomBytes(1)[0] % 250) + 1}`;
export const sha256 = (b: Buffer | string) => createHash('sha256').update(b).digest('hex');

// 1×1 PNG, 최소 PDF
export const PNG = Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==', 'base64');
export const pdf = (text: string, extra = '') =>
  Buffer.from(`%PDF-1.4\n1 0 obj << /Type /Catalog /Pages 2 0 R ${extra} >> endobj\n2 0 obj << /Type /Pages /Kids [] /Count 0 >> endobj\n% ${text}\ntrailer << /Root 1 0 R >>\n%%EOF\n`);

export interface Mail {
  id: string;
  at: number;
  to: string[];
  subject: string;
  text: string;
  idempotencyKey: string | null;
}

/**
 * 벽시계가 t(밀리초)를 넘을 때까지 기다린다. 기한·보유 기간처럼 서버가 Date.now() 로 판단하는 시험은 setTimeout 길이가 아니라
 * 이것으로 기다린다 — WSL2 의 벽시계는 호스트와 맞추느라 30초에 1초 넘게 뒤로 밀리기도 해서, 'n 초 잤다'가 '벽시계가 n 초 갔다'가 아니다.
 */
export async function untilWall(t: number) {
  while (Date.now() < t) await new Promise((r) => setTimeout(r, Math.min(200, Math.max(10, t - Date.now()))));
}

export const mails = async (): Promise<Mail[]> => (await (await fetch(`${MOCK}/__mails`)).json()) as Mail[];

/**
 * 받은 메일 기다리기 — since 는 보내기 전 시각. WSL2 벽시계가 뒤로 밀리면 메일의 기록 시각(가짜 Resend 의 Date.now())이
 * since 보다 작게 찍힐 수 있어 2초 여유를 두고, 맞는 것 중 가장 늦게 온 것을 고른다(로그인 코드처럼 같은 제목이 여러 번 와도 최신).
 */
export async function waitMail(to: string, subject: RegExp, since: number, timeout = 15_000): Promise<Mail> {
  const end = performance.now() + timeout;
  while (performance.now() < end) {
    const list = (await (await fetch(`${MOCK}/__mails?to=${encodeURIComponent(to)}`)).json()) as Mail[];
    const m = list.filter((x) => x.to.includes(to) && x.at >= since - 2000 && subject.test(x.subject)).at(-1);
    if (m) return m;
    await new Promise((r) => setTimeout(r, 200));
  }
  throw new Error(`메일 없음: ${to} ${subject}`);
}

/** 시각과 상관없이 '이 뒤에 새로 온' 메일 — 보내기 전에 받은 메일 id 를 적어 두고 새 id 를 기다린다(같은 제목이 거듭 오는 로그인 코드용) */
export const mailIds = async (to: string) => new Set(((await (await fetch(`${MOCK}/__mails?to=${encodeURIComponent(to)}`)).json()) as Mail[]).map((m) => m.id));
export async function waitNewMail(to: string, subject: RegExp, before: Set<string>, timeout = 15_000): Promise<Mail> {
  const end = performance.now() + timeout;
  while (performance.now() < end) {
    const list = (await (await fetch(`${MOCK}/__mails?to=${encodeURIComponent(to)}`)).json()) as Mail[];
    const m = list.filter((x) => !before.has(x.id) && subject.test(x.subject)).at(-1);
    if (m) return m;
    await new Promise((r) => setTimeout(r, 150));
  }
  throw new Error(`새 메일 없음: ${to} ${subject}`);
}

export const inviteToken = (m: Mail) => m.text.match(/\/invite\/([0-9a-f]{64})/)![1];

export class Api {
  constructor(
    public ctx: APIRequestContext,
    public email: string,
  ) {}
  async get(path: string, status = 200) {
    const r = await this.ctx.get(path);
    await expectStatus(r, status, `GET ${path}`);
    return r.status() === 200 ? r.json() : null;
  }
  async raw(method: 'GET' | 'POST' | 'PUT' | 'DELETE', path: string, data?: unknown) {
    return this.ctx.fetch(path, { method, data: data === undefined ? undefined : data, headers: data === undefined ? {} : { 'Content-Type': 'application/json' } });
  }
  async post(path: string, data: unknown = {}, status = 200) {
    const r = await this.ctx.post(path, { data, headers: { 'Content-Type': 'application/json' } });
    await expectStatus(r, status, `POST ${path}`);
    return r.json().catch(() => null);
  }
  async put(path: string, data: unknown, status = 200) {
    const r = await this.ctx.put(path, { data, headers: { 'Content-Type': 'application/json' } });
    await expectStatus(r, status, `PUT ${path}`);
    return r.json().catch(() => null);
  }
  async upload(path: string, fields: Record<string, string>, files: { name: string; mimeType: string; buffer: Buffer }[], status = 201) {
    const multipart: Record<string, string | { name: string; mimeType: string; buffer: Buffer }> = { ...fields };
    // Playwright multipart 는 같은 키를 여러 번 못 넣는다 — 파일 하나씩
    if (files[0]) multipart.files = files[0];
    const r = await this.ctx.post(path, { multipart });
    await expectStatus(r, status, `UPLOAD ${path}`);
    return r.json().catch(() => null);
  }
}

async function expectStatus(r: APIResponse, status: number, label: string) {
  if (r.status() !== status) throw new Error(`${label} → ${r.status()} (기대 ${status}): ${(await r.text()).slice(0, 400)}`);
}

export async function login(email: string, opts: { cache?: boolean } = {}): Promise<Api> {
  const file = `test-results/.session-${email.replace(/[^a-z0-9]/gi, '_')}.json`;
  mkdirSync('test-results', { recursive: true });
  const headers = { Origin: BASE, 'CF-Connecting-IP': fakeIp() };
  if (opts.cache && existsSync(file)) {
    const ctx = await request.newContext({ baseURL: BASE, extraHTTPHeaders: headers, storageState: file });
    const me = await (await ctx.get('/api/me')).json();
    if (me.user?.email === email) return new Api(ctx, email);
    await ctx.dispose();
  }
  const ctx = await request.newContext({ baseURL: BASE, extraHTTPHeaders: headers });
  const before = await mailIds(email);
  const s = await ctx.post('/api/auth/email-otp/send-verification-otp', { data: { email, type: 'sign-in' } });
  expect(s.status(), await s.text()).toBe(200);
  const code = (await waitNewMail(email, /로그인 코드/, before)).subject.match(/\d{6}/)![0];
  const v = await ctx.post('/api/auth/sign-in/email-otp', { data: { email, otp: code } });
  expect(v.status(), await v.text()).toBe(200);
  if (opts.cache) await ctx.storageState({ path: file });
  return new Api(ctx, email);
}

/** 초대 메일의 링크로 로그인·수락 */
export async function acceptInvite(email: string, since: number): Promise<Api> {
  const m = await waitMail(email, /초대/, since);
  const api = await login(email);
  await api.post(`/api/invitations/${inviteToken(m)}/accept`);
  return api;
}

export async function ownerApi() {
  const api = await login(OWNER, { cache: true });
  const me = await api.get('/api/me');
  const ws = me.workspaces[0].id as string;
  // 업체 소유자가 이용약관에 동의해야 프로젝트를 만들고 사람을 초대할 수 있다(한 번만)
  const dash = await api.get(`/api/w/${ws}`);
  if (!dash.terms.accepted) await api.post(`/api/w/${ws}/terms/accept`, { version: dash.terms.version, agree: true });
  return { api, ws };
}

/** 운영자가 새 업체를 만들고 소유자가 초대를 수락한 상태(약관 동의 전) */
export async function newWorkspace(label: string) {
  const ops = await login(OPERATOR, { cache: true });
  // 이메일은 영문만(업체 이름에만 label 을 쓴다)
  const email = `own-${randomBytes(3).toString('hex')}-${run}@studio-new.test`.toLowerCase();
  const since = Date.now();
  await ops.post('/api/ops/workspaces', { name: `${label} 업체 ${run}`, ownerEmail: email, ownerName: '남대표' }, 201);
  const m = await waitMail(email, /초대/, since);
  const owner = await login(email);
  await owner.post(`/api/invitations/${inviteToken(m)}/accept`);
  const me = await owner.get('/api/me');
  const ws = me.workspaces.find((w: { name: string }) => w.name === `${label} 업체 ${run}`).id as string;
  return { ops, owner, ws, email, name: `${label} 업체 ${run}` };
}

/**
 * 프로젝트 + 프로젝트 관리자(업체에 새로 초대) + 고객 셋(승인자·참여자·열람자).
 * owner 는 그 프로젝트의 관리자(실제 업무처럼 프로젝트마다 다른 사람), boss 는 업체 소유자.
/**
 * 내 요청의 진행 알림, 여러 요청 한꺼번에, 다른 프로젝트 범위에서 시작, 요청 CSV.
 */
import { test, expect } from '@playwright/test';
import { confirmScope, mailIds, mails, pdf, run, setupProject, waitMail } from './api';

test.describe.configure({ mode: 'serial' });
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

test('내 요청의 진행 — 범위 판단·작업 시작·납품·완료를 요청한 고객에게만, 끌 수 있다', async () => {
  const s = await setupProject(`진행알림 ${run}`);
  await confirmScope(s);
  const p = s.emails.participant;
  const t0 = Date.now();
  const { number, id } = await s.participant.post(`/api/p/${s.pid}/requests`, { title: `배너 교체 ${run}` }, 201);
  await s.owner.post(`/api/p/${s.pid}/requests/${number}`, { classification: 'in_scope', triageNote: '시안 교체는 포함 항목입니다.' });
  const m1 = await waitMail(p, new RegExp(`요청 #${number} 범위 안`), t0);
  expect(m1.text).toContain('시안 교체는 포함 항목입니다.');
  await s.owner.post(`/api/p/${s.pid}/requests/${number}`, { status: 'in_progress' });
  await waitMail(p, new RegExp(`요청 #${number} 작업을 시작했습니다`), t0);
  // 담당자 지정·우선순위 같은 내부 변경은 알리지 않는다
  await s.owner.post(`/api/p/${s.pid}/requests/${number}`, { priority: 'high' });

  // 납품 → 요청한 고객에게(검수 요청을 받는 승인자에게는 따로 보내지 않는다)
  const { number: rel } = await s.owner.post(`/api/p/${s.pid}/releases`, { versionLabel: 'v1.0', title: '납품', criteria: ['보인다'], requestIds: [id] }, 201);
  await s.owner.upload(`/api/p/${s.pid}/releases/${rel}/files`, {}, [{ name: 'a.pdf', mimeType: 'application/pdf', buffer: pdf(`n ${run}`) }]);
  const { approvalId } = await s.owner.post(`/api/p/${s.pid}/releases/${rel}/issue`, { approverId: s.approverId });
  await waitMail(p, new RegExp(`요청 #${number} 납품 — v1.0 검수 중`), t0);
  const view = await s.approver.get(`/api/p/${s.pid}/approvals/${approvalId}`);
  await s.approver.post(`/api/p/${s.pid}/approvals/${approvalId}/decision`, {
    decision: 'approved',
    acknowledged: true,
    snapshotSha256: view.approval.snapshotSha256,
    criteria: (view.approval.snapshot.subject.criteria as { id: string }[]).map((c) => ({ id: c.id, result: 'ok' })),
  });
  await waitMail(p, new RegExp(`요청 #${number} 완료 — v1.0 검수 승인`), t0);
  await sleep(600);
  const all = (await mails()).filter((m) => m.at >= t0 - 2000 && m.subject.includes(`[진행알림 ${run}]`) && /요청 #/.test(m.subject));
  expect(all.filter((m) => m.to.includes(p)).length).toBe(4);
  expect(all.filter((m) => m.to.includes(s.emails.approver) && /요청 #/.test(m.subject) && !/새 요청/.test(m.subject))).toEqual([]);
  expect(all.filter((m) => /우선순위/.test(m.subject))).toEqual([]);

  // 업체가 옮겨 적은 요청은 고객에게 알리지 않는다(여기부터 새로 온 메일은 id 로 가린다 — 시각은 WSL 벽시계 탓에 믿지 않는다)
  const before = await mailIds(p);
  const imp = await s.owner.post(`/api/p/${s.pid}/requests/import`, { source: 'kakao', items: [{ title: `옮긴 요청 ${run}`, text: '원문', author: '최참여' }] }, 201);
  await s.owner.post(`/api/p/${s.pid}/requests/${imp.first}`, { classification: 'out_of_scope' });

  // 끄면 보내지 않는다(기록은 skipped)
  await s.participant.post('/api/me/notifications', { mine: false });
  expect((await s.participant.get('/api/me/notifications')).mine).toBe(false);
  const { number: n2 } = await s.participant.post(`/api/p/${s.pid}/requests`, { title: `두 번째 ${run}` }, 201);
  await s.owner.post(`/api/p/${s.pid}/requests/${n2}`, { status: 'declined', reason: '이번 범위에서 하지 않기로 했습니다.' });
  await sleep(1500);
  expect((await mails()).filter((m) => !before.has(m.id) && m.to.includes(p) && /요청 #/.test(m.subject))).toEqual([]);
  await s.participant.post('/api/me/notifications', { mine: true });
});

test('여러 요청 한꺼번에 — 관리자만, 건마다 같은 규칙, 안 되는 건은 이유와 함께 남는다', async () => {
  const s = await setupProject(`일괄 ${run}`);
  await confirmScope(s);
  const imp = await s.owner.post(
    `/api/p/${s.pid}/requests/import`,
    { source: 'kakao', items: [1, 2, 3].map((i) => ({ title: `카톡 요청 ${i}`, text: `원문 ${i}`, author: '박승인' })) },
    201,
  );
  const [a, b, c] = [imp.first, imp.first + 1, imp.first + 2];
  // 고객·개발 담당자는 못 한다
  expect((await s.participant.raw('POST', `/api/p/${s.pid}/requests/bulk`, { numbers: [a], classification: 'in_scope' })).status()).toBe(403);
  const r1 = await s.owner.post(`/api/p/${s.pid}/requests/bulk`, { numbers: [a, b, 9999], classification: 'in_scope' });
  expect(r1.done).toBe(2);
  expect(r1.results.find((x: { number: number }) => x.number === 9999)).toMatchObject({ ok: false, message: '없는 요청입니다.' });
  const list = (await s.owner.get(`/api/p/${s.pid}/requests`)).requests as { number: number; status: string; classification: string }[];
  expect(list.filter((x) => [a, b].includes(x.number)).every((x) => x.classification === 'in_scope' && x.status === 'planned')).toBe(true);

  // 담당자: 이 프로젝트의 업체 사람만(고객은 안 된다) — 한 건 화면도 같은 규칙
  const pmId = (await s.owner.get('/api/me')).user.id as string;
  const assignees = (await s.owner.get(`/api/p/${s.pid}/requests`)).assignees as { id: string }[];
  expect(assignees.some((x) => x.id === pmId)).toBe(true);
  const r2 = await s.owner.post(`/api/p/${s.pid}/requests/bulk`, { numbers: [a, b], assigneeId: s.approverId });
  expect(r2.done).toBe(0);
  expect(r2.results[0].message).toContain('업체 사람만');
  expect((await s.owner.raw('POST', `/api/p/${s.pid}/requests/${a}`, { assigneeId: s.approverId })).status()).toBe(400);
  expect((await s.owner.post(`/api/p/${s.pid}/requests/bulk`, { numbers: [a, b], assigneeId: pmId })).done).toBe(2);

  // 진행 안 함: 이유 없으면 건마다 실패, 있으면 된다
  const r3 = await s.owner.post(`/api/p/${s.pid}/requests/bulk`, { numbers: [c], status: 'declined', reason: '' });
  expect(r3.results[0]).toMatchObject({ ok: false });
  expect((await s.owner.post(`/api/p/${s.pid}/requests/bulk`, { numbers: [c], status: 'declined', reason: '중복된 요청입니다.' })).done).toBe(1);
  // 이력에 건마다 남는다
  const hist = JSON.stringify(await s.approver.get(`/api/p/${s.pid}/activity`));
  expect(hist).toContain(`요청 #${a} 합의 범위 안으로 판단`);
  expect(hist).toContain(`요청 #${c} 진행하지 않기로 함 — 중복된 요청입니다.`);
  // 바꿀 것을 안 주면 거절
  expect((await s.owner.raw('POST', `/api/p/${s.pid}/requests/bulk`, { numbers: [a] })).status()).toBe(400);
});

test('다른 프로젝트 범위에서 시작 — 같은 업체, 볼 수 있는 프로젝트의 확인된 범위만', async () => {
  const A = await setupProject(`범위원본 ${run}`);
  await confirmScope(A);
  const B = await setupProject(`범위복사 ${run}`);
  // B 의 관리자는 A 에 배정되지 않았다 → 목록에 없고, 직접 줘도 거절
  expect((await B.owner.get(`/api/p/${B.pid}/scope/sources`)).sources.some((x: { projectName: string }) => x.projectName === `범위원본 ${run}`)).toBe(false);
  const aVersion = (await A.owner.get(`/api/p/${A.pid}/scope`)).versions[0];
  expect((await B.owner.raw('POST', `/api/p/${B.pid}/scope`, { fromVersionId: aVersion.id })).status()).toBe(400);
  // 업체 소유자는 모든 프로젝트를 본다
  const src = (await B.boss.get(`/api/p/${B.pid}/scope/sources`)).sources as { id: string; items: number }[];
  expect(src.find((x) => x.id === aVersion.id)?.items).toBe(10);
  await B.boss.post(`/api/p/${B.pid}/scope`, { fromVersionId: aVersion.id }, 201);
  const draft = (await B.owner.get(`/api/p/${B.pid}/scope`)).versions[0];
  expect(draft).toMatchObject({ version: 1, status: 'draft', title: `범위복사 ${run} 작업 범위`, summary: aVersion.summary, schedule: aVersion.schedule });
  expect(draft.items.include.map((i: { text: string }) => i.text)).toEqual(aVersion.items.include.map((i: { text: string }) => i.text));
  expect(draft.items.criterion.length).toBe(3);
  // 원본은 그대로
  expect((await A.owner.get(`/api/p/${A.pid}/scope`)).versions.length).toBe(1);
  // 고객은 목록을 못 본다
  expect((await B.approver.ctx.get(`/api/p/${B.pid}/scope/sources`)).status()).toBe(403);
});

test('요청 CSV — 역할에 맞는 칸, 수식으로 읽히는 첫 글자는 글자로', async () => {
