// 테스트용 가짜 Resend — 실제로 보내지 않고 기록만 한다.
//   node tests/mock-resend.mjs [port]
//
// POST /emails          한 통(인증: Bearer re_test_only). Idempotency-Key 가 같으면 한 번만 기록
// POST /__fail {n}      다음 n 통을 500 으로 실패시킨다(알림 재시도 시험)
// POST /__fail {to, on}  그 주소로 가는 메일만 계속 실패(on:false 로 풀기) — 다른 시험과 겹치지 않게
// GET/DELETE /__mails   기록 보기/비우기(GET ?to=주소 로 받는 사람만)
import { createServer } from 'node:http';

const port = +(process.argv[2] ?? 8799);
let mails = [];
let failNext = 0;
const failTo = new Set();
const seen = new Map();

createServer(async (req, res) => {
  const chunks = [];
  for await (const c of req) chunks.push(c);
  const raw = Buffer.concat(chunks).toString('utf8');
  const send = (status, body) => {
    res.writeHead(status, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(body));
  };
  const url = new URL(req.url, `http://127.0.0.1:${port}`);
  if (url.pathname === '/__mails' && req.method === 'GET') {
    const to = url.searchParams.get('to');
    return send(200, to ? mails.filter((m) => (Array.isArray(m.to) ? m.to : [m.to]).includes(to)) : mails);
  }
  if (url.pathname === '/__mails' && req.method === 'DELETE') {
    mails = [];
    seen.clear();
    failNext = 0;
    failTo.clear();
    return send(200, { ok: true });
  }
  if (url.pathname === '/__fail' && req.method === 'POST') {
    const b = JSON.parse(raw || '{}');
    if (b.to) {
      if (b.on === false) failTo.delete(b.to);
      else failTo.add(b.to);
      return send(200, { failTo: [...failTo] });
    }
    failNext = Number(b.n ?? 1);
    return send(200, { failNext });
  }
  if (url.pathname === '/emails' && req.method === 'POST') {
    if (req.headers.authorization !== 'Bearer re_test_only') return send(401, { message: 'bad key' });
    let to = [];
    try {
      to = [JSON.parse(raw).to].flat();
    } catch {}
    if (to.some((a) => failTo.has(a))) return send(500, { message: 'mock failure(to)' });
    if (failNext > 0) {
      failNext--;
      return send(500, { message: 'mock failure' });
    }
    let m;
    try {
      m = JSON.parse(raw);
    } catch {
      return send(400, { message: 'bad json' });
    }
    const key = req.headers['idempotency-key'];
    if (key && seen.has(key)) return send(200, { id: seen.get(key) });
    const id = `mock-${mails.length + 1}`;
    if (key) seen.set(key, id);
    mails.push({ id, at: Date.now(), idempotencyKey: key ?? null, ...m });
    return send(200, { id });
  }
  send(404, { message: 'not found' });
}).listen(port, '127.0.0.1', () => console.log(`mock resend on http://127.0.0.1:${port}`));
/**
 * 내 요청의 진행 알림 — 고객이 남긴 요청이 범위 판단·진행 안 함·작업 시작·납품·완료로 바뀌면 그 고객에게 알린다.
 * 업체 사람이 옮겨 적은 요청(요청한 사람이 업체 쪽)과 바꾼 사람 자신에게는 보내지 않는다. ‘내 요청의 진행’ 알림을 끈 사람은 outbox 에서 건너뛴다.
 */
import type { Db, Tx } from '../db/client';
import { enqueue } from './outbox';
import { projectPeople, type ProjectAccess } from '../access';

export interface RequestRef {
  id: string;
  number: number;
  title: string;
  createdBy: string;
}

export async function notifyRequesters(
  tx: Tx,
  db: Db,
  env: Env,
  a: Pick<ProjectAccess, 'project' | 'workspace' | 'user'>,
  requests: RequestRef[],
  msg: { key: string; subject: (r: RequestRef) => string; lines: (r: RequestRef) => string[]; except?: Set<string> },
): Promise<string[]> {
  if (!requests.length) return [];
  const clients = new Map((await projectPeople(db, a.project, ['approver', 'participant', 'viewer'])).map((p) => [p.id, p]));
  const ids: string[] = [];
  for (const r of requests) {
    const p = clients.get(r.createdBy);
    if (!p || p.id === a.user.id || msg.except?.has(p.id)) continue;
    ids.push(
      enqueue(tx, db, env, {
        workspaceId: a.workspace.id,
        projectId: a.project.id,
        kind: 'request_update',
        to: p,
        subject: msg.subject(r),
        lines: msg.lines(r),
        path: `/p/${a.project.id}/requests/${r.number}`,
        dedupeKey: `request_update/${r.id}/${msg.key}`,
      }),
    );
  }
  return ids;
}
