/**
 * 알림 — 업무 변경과 같은 Tx 로 notification_outbox 에 쌓고, 커밋 뒤에 보낸다.
 * 보내기에 실패해도 업무 기록은 그대로다. 실패한 메일은 Cron(5분)이 1·5·30분·2·12시간 간격으로 다시 보내고,
 * 여섯 번 실패하면 dead 로 남긴다. 같은 dedupe_key 는 한 번만 쌓인다.
 */
import { and, eq, inArray, lt, lte } from 'drizzle-orm';
import { getDb, schema, type Db, type Tx } from '../db/client';
import { newId } from '../lib/util';
import { mailText, sendMail } from './mail';
import { MAIL_CATEGORY } from '../../shared/domain';

const BACKOFF_MS = [60_000, 5 * 60_000, 30 * 60_000, 2 * 3600_000, 12 * 3600_000];
export const MAX_ATTEMPTS = 6;

export interface Notice {
  workspaceId: string | null;
  projectId: string | null;
  kind: string;
  to: { email: string; name: string; id?: string };
  subject: string;
  lines: string[];
  path?: string;
  dedupeKey: string;
  /** 자동 문의 메일 — 보내기 직전에 이 문의가 아직 자동 처리 중이고 세대가 같은지 본다(사람이 인수하면 보내지 않는다) */
  guard?: { inquiryId: string; epoch: number };
  /** 링크를 APP_ORIGIN 이 아닌 전체 주소로(공개 문의 화면 등) — path 와 함께 쓰지 않는다 */
  url?: string;
}

export function enqueue(tx: Tx, db: Db, env: Env, n: Notice): string {
  const id = newId();
  const now = Date.now();
  tx.add(
    db
      .insert(schema.outbox)
      .values({
        id,
        workspaceId: n.workspaceId,
        projectId: n.projectId,
        kind: n.kind,
        toEmail: n.to.email,
        toName: n.to.name,
        toUserId: n.to.id ?? null,
        guardInquiryId: n.guard?.inquiryId ?? null,
        guardEpoch: n.guard?.epoch ?? null,
        subject: n.subject.slice(0, 200),
        body: mailText([`${n.to.name ? `${n.to.name}님,` : '안녕하세요,'}`, '', ...n.lines], n.url ?? (n.path ? `${env.APP_ORIGIN}${n.path}` : undefined)),
        dedupeKey: n.dedupeKey,
        status: 'pending',
        attempts: 0,
        nextAttemptAt: now,
        createdAt: now,
      })
      .onConflictDoNothing(),
  );
  return id;
}

