    .select()
    .from(schema.outbox)
    .where(
      ids?.length
        ? and(inArray(schema.outbox.id, ids), eq(schema.outbox.status, 'pending'))
        : and(eq(schema.outbox.status, 'pending'), lte(schema.outbox.nextAttemptAt, now)),
    )
    .limit(50);
  let sent = 0;
  let failed = 0;
  const muted = await mutedFor(env, rows);
  const stale = await staleGuards(env, rows);
  for (const row of rows) {
    if (stale.has(row.id)) {
      // 사람이 인수했거나(세대가 바뀜) 문의가 끝났다 — 자동 메일은 보내지 않고 그렇게 남긴다
      await env.DB.prepare(`UPDATE notification_outbox SET status = 'skipped', last_error = 'superseded' WHERE id = ? AND status = 'pending'`).bind(row.id).run();
      continue;
    }
    if (muted.has(row.id)) {
      // 받는 사람이 꺼 둔 종류 — 보내지 않고 그렇게 남긴다
      await env.DB.prepare(`UPDATE notification_outbox SET status = 'skipped', last_error = 'muted' WHERE id = ? AND status = 'pending'`).bind(row.id).run();
      continue;
    }
    // 선점: 두 실행이 같은 메일을 동시에 보내지 않게
    const claim = await env.DB.prepare(
      `UPDATE notification_outbox SET status = 'sending', attempts = attempts + 1, next_attempt_at = ? WHERE id = ? AND status = 'pending'`,
    )
      .bind(now, row.id)
      .run();
    if ((claim.meta?.changes ?? 0) !== 1) continue;
    const r = await sendMail(env, { to: row.toEmail, subject: row.subject, text: row.body, idempotencyKey: `outbox/${row.id}` });
    const attempts = row.attempts + 1;
    if (r.ok) {
      sent++;
      await db.update(schema.outbox).set({ status: 'sent', sentAt: Date.now(), lastError: '' }).where(eq(schema.outbox.id, row.id));
    } else {
      failed++;
      const dead = attempts >= MAX_ATTEMPTS;
      await db
        .update(schema.outbox)
        .set({
          status: dead ? 'dead' : 'pending',
          lastError: r.error,
          nextAttemptAt: Date.now() + (env.TEST_BACKOFF_MS !== undefined ? Number(env.TEST_BACKOFF_MS) : BACKOFF_MS[Math.min(attempts - 1, BACKOFF_MS.length - 1)]),
        })
        .where(eq(schema.outbox.id, row.id));
      console.error(`outbox: ${row.kind} ${r.error} attempt ${attempts}`);
    }
  }
  return { sent, failed };
}

/** 보내기 직전 검사 — 자동 문의 메일인데 문의가 자동 처리(bot)가 아니거나 세대가 바뀌었거나 끝난 것 */
async function staleGuards(env: Env, rows: { id: string; guardInquiryId: string | null; guardEpoch: number | null }[]): Promise<Set<string>> {
  const guarded = rows.filter((r) => r.guardInquiryId);
  if (!guarded.length) return new Set();
  const ids = [...new Set(guarded.map((r) => r.guardInquiryId!))];
  const inq = await env.DB.prepare(`SELECT id, handler, epoch, status FROM inquiries WHERE id IN (${ids.map(() => '?').join(',')})`)
    .bind(...ids)
    .all<{ id: string; handler: string; epoch: number; status: string }>();
  const by = new Map((inq.results ?? []).map((x) => [x.id, x]));
  return new Set(
    guarded
      .filter((r) => {
        const x = by.get(r.guardInquiryId!);
        return !x || x.handler !== 'bot' || x.epoch !== r.guardEpoch || ['declined', 'closed', 'converted'].includes(x.status);
      })
      .map((r) => r.id),
  );
}

/** 받는 사람이 그 분류의 알림을 꺼 둔 메일 id */
async function mutedFor(env: Env, rows: { id: string; kind: string; toUserId: string | null }[]): Promise<Set<string>> {
  const check = rows.filter((r) => r.toUserId && MAIL_CATEGORY[r.kind]);
  if (!check.length) return new Set();
  const users = [...new Set(check.map((r) => r.toUserId!))];
  const prefs = await env.DB.prepare(`SELECT user_id, requests, comments, results, mine FROM notification_prefs WHERE user_id IN (${users.map(() => '?').join(',')})`)
    .bind(...users)
    .all<{ user_id: string; requests: number; comments: number; results: number; mine: number }>();
  const by = new Map((prefs.results ?? []).map((p) => [p.user_id, p]));
  return new Set(check.filter((r) => by.get(r.toUserId!)?.[MAIL_CATEGORY[r.kind]!] === 0).map((r) => r.id));
}
