if (occupied) { console.log('진단 생략: 기존 mock 서버 사용 중'); process.exit(0); }
const child = spawn(process.execPath, ['tests/mock-resend.mjs', '8799'], {stdio:['ignore','pipe','pipe']});
try {
  await new Promise((resolve,reject)=>{child.stdout.once('data',resolve);child.once('error',reject);child.once('exit',code=>reject(new Error("'`mock exit ${code}`)));});
  const mod = new SourceTextModule(stripTypeScriptTypes(readFileSync('"'tests/api.ts','utf8')), {identifier:'tests/api.ts'});
  await mod.link(async spec => {
    const actual = await import(spec === '@playwright/test' ? 'file:///home/hkjang/node_modules/playwright/test.mjs' : spec);
    return new SyntheticModule(Object.keys(actual), function(){for(const k of Object.keys(actual)) this.setExport(k,actual[k]);});
  });
  await mod.evaluate();
  const {mailIds,waitMail,waitNewMail,mails} = mod.namespace;
  const to = 'scout-clock-probe@example.invalid';
  const before = await mailIds(to);
  const since = Date.now();
  const response = await fetch('http://127.0.0.1:8799/emails',{method:'POST',headers:{Authorization:'Bearer re_test_only','Content-Type':'application/json'},body:JSON.stringify({to:[to],subject:'요청 #1 작업을 시작했습니다',text:'진단용',at:since-5000})});
  assert.equal(response.status,200);
  assert.equal((await mails()).length,1);
  await assert.rejects(waitMail(to,/요청 #1 작업을 시작했습니다/,since,250),/메일 없음/);
  const received = await waitNewMail(to,/요청 #1 작업을 시작했습니다/,before,250);
  assert.equal(received.at,since-5000);
  const after = await mailIds(to);
  await assert.rejects(waitNewMail(to,/요청 #1 작업을 시작했습니다/,after,250),/새 메일 없음/);
  console.log('PASS 진단: 실제 tests/api.ts 함수 + mock-resend HTTP. 수신 메일 at=since-5000이면 waitMail 실패, waitNewMail 성공, 이미 본 ID는 거절. 실제 업무 API/당시 시계 역행 재현은 아님.');
} finally {child.kill('SIGTERM'); await new Promise(resolve=>child.once('exit',resolve));}
